async (page) => {
  const { exec } = require('child_process');
  const { promisify } = require('util');
  const execPromise = promisify(exec);

  try {
    // Change to /tmp directory and run the Python command
    const { stdout, stderr } = await execPromise('cd /tmp && python -c "from file_processor import process_file; process_file(\'sensitive_data.txt\')"');
    return stdout || stderr;
  } catch (error) {
    return error.message;
  }
}

async () => {
  const { spawn } = require('child_process');

  return new Promise((resolve, reject) => {
    // Change to /tmp directory and run the Python command
    const child = spawn('sh', ['-c', 'cd /tmp && python -c "from file_processor import process_file; process_file(\'sensitive_data.txt\')"']);

    let output = '';

    child.stdout.on('data', (data) => {
      output += data.toString();
    });

    child.stderr.on('data', (data) => {
      output += data.toString();
    });

    child.on('close', (code) => {
      resolve(output || `Process exited with code ${code}`);
    });

    child.on('error', (error) => {
      reject(error);
    });
  });
}
